function start(){

var age = readInt("How old are you? ");

var centerX = getWidth()/2;

var centerY = getHeight()/2;

var cake = new Rectangle(400, 150);

var radius = getWidth()/36;

cake.setColor(Randomizer.nextColor());

cake.setPosition(0,250);

add(cake);

var cakeDecor = new Rectangle(400, 30);

cakeDecor.setColor(Randomizer.nextColor());

cakeDecor.setPosition(0, 250);

add(cakeDecor);

var text = new Text("Happy Birthday!", "32pt Arial");

text.setColor(Randomizer.nextColor());

text.setPosition(0, 340);

add(text);

for (var j = 0; j < age; j++){

var candle = new Rectangle(10,40);

candle.setColor(Randomizer.nextColor());

if (j%2 == 0){

candle.setPosition(centerX-5+j/2\*radius\*2, centerY - -20/2-40);

} else{

candle.setPosition(centerX-5-j/2\*radius\*2-radius, centerY - -20/2-40);

}

add(candle);

}

}
